import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;

        int n = sc.nextInt();
        String s = sc.next();

        long sala = 1;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == 'E') {
                sala = 2 * sala;
            } else if (c == 'D') {
                sala = 2 * sala + 1;
            }
        }

        System.out.println(sala);
    }
}
